INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('fajr_period', 'time', 'فريضة الصبح جماعة في المسجد للرجال، بأذكار المسجد والذهاب إليه المتقدمة', 'Het fadjr-gebed in gemeenschap in de moskee voor de mannen, met de adhkaar van het gaan en het binnentreden.', 'The fajr prayer in congregation at the mosque for men, with the adhkaar of walking and entering.', 'يمشي إليها بسكينة، وله بكل خطوة حسنة، ومن مشى في الظلمة فله النور التام يوم القيامة [أبو داود (561)، وصححه الألباني].', 'Men loopt er in rust naartoe, met voor elke stap een goede daad; wie in de duisternis loopt, heeft het volmaakte licht op de Dag der Opstanding [Aboe Daawoed 561].', 'One walks to it in calm, with a good deed for each step; whoever walks in the darkness has the perfect light on the Day of Resurrection [Aboo Daawood 561].', 'دخول الجنة بالبردين، وذمة الله لمصلي الصبح، وشهود الملائكة: ﴿إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾ [الإسراء: 78].', 'Het binnengaan van het Paradijs door de twee koele gebeden, Allaahs bescherming voor wie het ochtendgebed bidt, en de aanwezigheid van de engelen: ''Waarlijk, de recitatie van de dageraad wordt bijgewoond.''', 'Entering Paradise by the two cool prayers, Allaah''s protection for whoever prays fajr, and the presence of the angels: ''Indeed, the recitation of dawn is witnessed.''', 'فريضة الفجر جماعة', 'tijdstip', 'time', 1, 281),('fajr_period', 'time', 'أذكار دبر الفجر ثم أذكار الصباح كاملة ــ تقدمت بأقسامها ــ ثم المكث للذكر حتى تطلع الشمس وترتفع، ثم ركعتان', 'De adhkaar na fadjr, daarna de volledige ochtend-adhkaar, en dan — voor wie kan — blijven zitten in dhikr tot de zon is opgekomen, gevolgd door twee rak3ah.', 'The post-fajr adhkaar, then the full morning adhkaar, and — for whoever can — remaining in dhikr until sunrise, followed by two rak3ahs.', 'من كان له عمل أو عيال قام لحاجته وأتى بالأذكار في طريقه ومركبه؛ فالذكر لا يشترط له المكان.', 'Wie werk of gezin heeft, staat op voor zijn behoefte en verricht de adhkaar op zijn weg en in zijn vervoermiddel; want de dhikr vereist geen (vaste) plaats.', 'Whoever has work or family rises for his need and performs the adhkaar on his way and in his transport; for dhikr requires no (fixed) place.', 'أجر الجلسة منصوص: «كأجر حجة وعمرة تامة تامة تامة».', 'De beloning van de zitting is uitdrukkelijk: ''als de beloning van een hadj en 3umrah, volledig, volledig, volledig''.', 'The reward of the sitting is stated: ''like the reward of a hajj and 3umrah, complete, complete, complete''.', 'أذكار دبر الفجر والصباح', 'tijdstip', 'time', 1, 282),('duha_work', 'time', 'ركعتان فأكثر، وأفضل وقتها إذا اشتد الضحى ورمِضت الفصال من الحر', 'Het duhaa-gebed: twee rak3ah of meer; de beste tijd is wanneer de hitte sterk wordt.', 'The duhaa prayer: two rak3ahs or more; its best time is when the heat intensifies.', 'من صلاها أول ارتفاع الشمس فقد أتى بجلسة الشروق وركعتيها، ومن أخرها لشدة الضحى أدرك صلاة الأوابين.', 'Wie het bidt bij het eerste stijgen van de zon, heeft de zitting van zonsopgang en haar twee rak3ah verricht; en wie het uitstelt tot de hitte van de duhaa, treft het gebed van de oprecht berouwvollen.', 'Whoever prays it at the sun''s first ascent has performed the sunrise sitting and its two rak3ahs; and whoever delays it to the heat of duhaa catches the prayer of the oft-returning.', 'تجزئ عن صدقة المفاصل الثلاثمائة والستين كما تقدم [مسلم (720)].', 'Zij vervangt de sadaqah van de driehonderdzestig gewrichten, zoals eerder vermeld [Muslim 720].', 'It substitutes for the charity of the three hundred sixty joints, as mentioned earlier [Muslim 720].', 'صلاة الضحى', 'tijdstip', 'time', 1, 283),('duha_work', 'time', 'البكور إلى العمل والتجارة بعد ورد الصباح، بنية الاستغناء عن الناس والإنفاق على العيال', 'Vroeg op weg naar werk en handel na de ochtend-dhikr, met de intentie van onafhankelijkheid en het onderhouden van het gezin.', 'Setting out early to work and trade after the morning dhikr, intending self-sufficiency and providing for the family.', 'يستفتح تجارته بعد الفجر وأوراده؛ ففي البركة الموعودة عوض عن سهر يضيّع الفجر.', 'Men opent zijn handel na de fadjr en zijn wird; in de beloofde zegen ligt de vergoeding voor een nachtwake die de fadjr verwaarloost.', 'One opens his trade after fajr and his wird; in the promised blessing is the compensation for a vigil that neglects fajr.', 'دعاؤه صلى الله عليه وسلم بالبركة للمبكرين، وقصة صخر شاهد تطبيق الصحابي وثمرته.', 'Zijn smeekbede (vrede en zegeningen zij met hem) om zegen voor wie vroeg opstaan, en het verhaal van Sakhr getuigt van de toepassing van de metgezel en de vrucht ervan.', 'His supplication (peace and blessings be upon him) for blessing for the early risers, and Sakhr''s account testifies to the companion''s application and its fruit.', 'البكور إلى العمل والتجارة', 'tijdstip', 'time', 1, 284),('duha_work', 'time', 'الصدق والبيان في كل عقد ومعاملة، وذكر الله في السوق بذكره المتقدم [الترمذي (3428)]', 'Eerlijkheid en duidelijkheid in elke transactie, en de dhikr van de markt bij het betreden ervan.', 'Honesty and clarity in every transaction, and the market dhikr upon entering it.', 'يدخل السوق بذكره، ويتعامل بصدقه، فيجمع بين ربح الدنيا وربح الألف ألف حسنة.', 'Men betreedt de markt met zijn dhikr en handelt met zijn eerlijkheid, en verenigt zo de winst van de wereld en de winst van de miljoen goede daden.', 'One enters the market with his dhikr and deals with his honesty, thus combining the profit of the world and the profit of the million good deeds.', 'البركة للصادقَين منصوصة، والمحق للكاذبَين.', 'De zegen voor de twee eerlijken is uitdrukkelijk, en het wegnemen (van de zegen) voor de twee leugenaars.', 'The blessing for the two truthful is stated, and the removal (of blessing) for the two liars.', 'الصدق والذكر في السوق', 'tijdstip', 'time', 1, 285),('duha_work', 'time', 'ينفق على أهله محتسبا، مستحضرا أن لقمة يرفعها إلى فيِّ امرأته صدقة', 'Men onderhoudt zijn gezin met de intentie van beloning; zelfs de hap die hij zijn vrouw aanreikt is sadaqah.', 'One provides for his family hoping for reward; even the morsel he lifts to his wife''s mouth is charity.', 'يجدد نية الاحتساب إذا خرج لكسبه وإذا رجع بقوته.', 'Men vernieuwt de intentie van beloning wanneer men uitgaat om te verdienen en wanneer men terugkeert met zijn onderhoud.', 'One renews the intention of reward when going out to earn and when returning with one''s sustenance.', 'الفضل منصوص: «فهي له صدقة»، وأعظم الدينار دينار ينفقه الرجل على عياله [مسلم (994)].', 'De verdienste is uitdrukkelijk: ''het is voor hem een sadaqah'', en de grootste dinaar is de dinaar die de man aan zijn gezin besteedt [Muslim 994].', 'The merit is stated: ''it is a charity for him'', and the greatest dinar is the one a man spends on his family [Muslim 994].', 'النفقة على الأهل محتسبا', 'tijdstip', 'time', 1, 286),('dhuhr_time', 'time', 'الظهر جماعة، وأربع قبلها وثنتان بعدها، مع أذكار دبر الصلاة المتقدمة', 'Dhuhr in gemeenschap, vier rak3ah ervoor en twee erna, met de adhkaar na het gebed.', 'Dhuhr in congregation, four rak3ahs before and two after, with the post-prayer adhkaar.', 'من فاتته الأربع قبلها قضاها بعدها؛ فقد فعلته عائشة عن النبي صلى الله عليه وسلم في معناه.', 'Wie de vier (rak3ah) vóór het (dhuhr-gebed) mist, haalt ze erna in; 3aa''ishah deed het van de Profeet (vrede en zegeningen zij met hem) in gelijke zin.', 'Whoever misses the four (rak3ahs) before (dhuhr) makes them up after it; 3aa''ishah did so from the Prophet (peace and blessings be upon him) to the same effect.', 'الأجر منصوص: بيت في الجنة لمن ثابر عليها كل يوم.', 'De beloning is uitdrukkelijk: een huis in het Paradijs voor wie er dagelijks op volhardt.', 'The reward is stated: a house in Paradise for whoever persists on it daily.', 'صلاة الظهر ورواتبها', 'tijdstip', 'time', 1, 287),('dhuhr_time', 'time', 'نومة خفيفة وسط النهار يستعين بها على قيام الليل وعمل النهار', 'Een korte middagslaap (qayloelah), tot steun voor het nachtgebed en het dagwerk.', 'A brief midday nap (qayloolah), aiding the night prayer and the day''s work.', 'وأثر الصحابة في يوم الجمعة: تقديم الصلاة ثم القيلولة والغداء بعدها؛ فيتصرف وقتها بحسب اليوم.', 'En het doen van de metgezellen op vrijdag: eerst het gebed, dan de middagslaap en de maaltijd erna; men schikt haar tijd dus naar de dag.', 'And the companions'' practice on Friday: the prayer first, then the nap and the meal after it; so one arranges its time according to the day.', 'العلة منصوصة: مخالفة الشياطين التي لا تقيل، والإعانة على القيام.', 'De reden is uitdrukkelijk: het verschillen van de shayaatien die geen middagslaap houden, en de steun voor het nachtgebed.', 'The reason is stated: differing from the devils who do not nap, and the aid for the night prayer.', 'القيلولة وسط النهار', 'tijdstip', 'time', 1, 288),('asr_time', 'time', 'العصر جماعة في وقتها، وليس لها راتبة مؤكدة، ومن صلى أربعا قبلها فحسن؛ لحديث: «رحم الله امرأ صلى قبل العصر أربعا» [أبو داود (1271)، والترمذي (430)، وحسنه الألباني]', '3asr in gemeenschap op zijn tijd; het heeft geen bevestigde raatibah, en wie er vier vóór bidt, doet goed.', '3asr in congregation at its time; it has no confirmed raatibah, and whoever prays four before it does well.', 'يحذر تأخيرها بانشغال آخر النهار؛ فالوعيد فيها أغلظ.', 'Men hoedt zich het uit te stellen door drukte aan het einde van de dag; want de waarschuwing erbij is strenger.', 'One guards against delaying it through the day''s end busyness; for the warning concerning it is sterner.', 'وفيها: «من صلى البردين دخل الجنة»، وتجتمع فيها ملائكة الليل والنهار [البخاري (555)].', 'Daarin: ''wie de twee koele gebeden bidt, treedt het Paradijs binnen'', en daarin verzamelen zich de engelen van nacht en dag [al-Bukhaarie 555].', 'In it: ''whoever prays the two cool prayers enters Paradise'', and in it the angels of night and day gather [al-Bukhaaree 555].', 'صلاة العصر', 'tijdstip', 'time', 1, 289),('asr_time', 'time', 'أذكار المساء كاملة ــ تقدمت بقسمها ــ والجلوس للذكر إلى الغروب لمن تيسر له، ولا صلاة نافلة بعد العصر حتى تغرب', 'De volledige avond-adhkaar, en het zitten in dhikr tot zonsondergang voor wie kan; geen vrijwillig gebed na 3asr tot de zon onder is.', 'The full evening adhkaar, and sitting in dhikr until sunset for whoever can; no voluntary prayer after 3asr until the sun sets.', 'من كان في عمله أتى بأذكاره حيث كان؛ فوقتها من العصر إلى الغروب ويمتد لأول الليل.', 'Wie aan het werk is verricht zijn adhkaar waar hij ook is; want hun tijd is van 3asr tot zonsondergang en strekt zich uit tot het begin van de nacht.', 'Whoever is at work performs his adhkaar wherever he is; for their time is from 3asr to sunset and extends to the start of the night.', 'أجر المجلس منصوص: أحب إلى النبي صلى الله عليه وسلم من عتق أربع رقاب.', 'De beloning van de zitting is uitdrukkelijk: de Profeet (vrede en zegeningen zij met hem) had het liever dan het vrijlaten van vier slaven.', 'The reward of the sitting is stated: the Prophet (peace and blessings be upon him) preferred it to freeing four slaves.', 'أذكار المساء والجلوس للذكر', 'tijdstip', 'time', 1, 290),('maghrib_isha', 'time', 'المغرب جماعة، وركعتان بعدها من الاثنتي عشرة، وعشر التهليلات دبرها لحرز الليلة ــ تقدمت ــ', 'Maghrib in gemeenschap, twee rak3ah erna, en de tien tahlielaat na de salaam als bescherming van de nacht.', 'Maghrib in congregation, two rak3ahs after it, and the ten tahleelaat after the salaam as the night''s protection.', 'ويكف صبيانه أول ساعة من الليل ويغلق بابه ويوكئ سقاءه مسميا؛ للحديث الآتي.', 'Men houdt zijn kinderen in het eerste uur van de nacht binnen, sluit zijn deur en bindt zijn waterzak dicht met de tasmiyah; wegens de volgende hadieth.', 'One keeps his children in during the first hour of the night, locks his door and ties his waterskin with the tasmiyah; per the following hadeeth.', 'حرز الليلة كلها بالتهليلات كما تقدم نصا.', 'Bescherming van de hele nacht door de tahlielaat, zoals eerder uitdrukkelijk vermeld.', 'Protection of the whole night by the tahleelaat, as previously stated explicitly.', 'صلاة المغرب وعشر التهليلات', 'tijdstip', 'time', 1, 291),('maghrib_isha', 'time', 'خمسة أعمال بالتسمية عند جنح الليل: كف الصبيان أول ساعة، وإغلاق الأبواب، وإيكاء الأسقية، وتخمير الآنية، وإطفاء ما يُخشى من النار عند النوم', 'Vijf handelingen met de tasmiyah bij het vallen van de avond: de kinderen binnenhouden in het eerste uur, de deuren sluiten, de waterzakken dichtbinden, het vaatwerk afdekken en de lampen doven bij het slapen.', 'Five acts with the tasmiyah at nightfall: keeping the children in during the first hour, locking the doors, tying the waterskins, covering the vessels, and extinguishing the lamps at bedtime.', 'هي أذكار عملية بيتية يعلّمها أهله وأولاده كل مساء.', 'Het zijn praktische huiselijke adhkaar die men zijn gezin en kinderen elke avond onderwijst.', 'They are practical household adhkaar one teaches one''s family and children every evening.', 'العلل منصوصة: انتشار الشياطين، وأن الشيطان لا يفتح بابا مغلقا ولا يكشف إناء مخمرا.', 'De redenen zijn uitdrukkelijk: het uitzwermen van de shayaatien, en dat de shaytaan geen gesloten deur opent noch een afgedekt vat opent.', 'The reasons are stated: the spreading of the devils, and that Satan opens no locked door nor uncovers a covered vessel.', 'أعمال التسمية عند جنح الليل', 'tijdstip', 'time', 1, 292),('maghrib_isha', 'time', 'العشاء جماعة، وركعتان بعدها، ثم لا سمر إلا في خير: علم، أو أنس بأهل، أو إكرام ضيف', '3ishaa'' in gemeenschap en twee rak3ah erna; daarna geen avondpraat behalve in het goede: kennis, gezelschap van het gezin of het eren van een gast.', '3ishaa'' in congregation and two rak3ahs after; then no night talk except in good: knowledge, family company, or honouring a guest.', 'السمر المستثنى: مع الأهل والضيف وفي مدارسة العلم؛ فقد سمر النبي صلى الله عليه وسلم مع أبي بكر في أمر المسلمين.', 'De uitgezonderde nachtpraat: met het gezin, de gast en in het bestuderen van kennis; de Profeet (vrede en zegeningen zij met hem) praatte ''s nachts met Aboe Bakr over een zaak van de moslims.', 'The excepted night talk: with the family, the guest and in studying knowledge; the Prophet (peace and blessings be upon him) talked at night with Aboo Bakr about a matter of the Muslims.', 'الأجر منصوص: قيام نصف الليل بجماعة العشاء، وتمامه بجماعة الفجر.', 'De beloning is uitdrukkelijk: het staan van een halve nacht door de 3ishaa'' in gemeenschap, en de volledige nacht door de fadjr in gemeenschap.', 'The reward is stated: standing half the night by 3ishaa'' in congregation, and the full night by fajr in congregation.', 'صلاة العشاء وترك السمر', 'tijdstip', 'time', 1, 293),('sleep_cycle', 'time', 'الوضوء، ونفض الفراش، والاضطجاع على اليمين، والقرآن والأذكار بتمامها، وجعل «أسلمت وجهي» آخر الكلام ــ تقدم كله بقسمه ــ', 'De taken van het slapen: woedoe, het uitkloppen van het bed, liggen op de rechterzij, de recitatie en adhkaar volledig, en ''aslamtu wadjhie'' als laatste woorden.', 'The duties of sleep: ablution, dusting the bed, lying on the right side, the full recitation and adhkaar, and ''aslamtu wajhee'' as one''s last words.', 'وينوي بنومه التقوي على قيام آخر الليل وفجر الغد؛ فينقلب نومه عبادة، كما قال معاذ رضي الله عنه: «إني أحتسب نومتي كما أحتسب قومتي» [البخاري (4341)].', 'Men beoogt met zijn slaap kracht voor het staan in het laatste deel van de nacht en de fadjr van morgen; zo wordt zijn slaap aanbidding, zoals Mu3aadh (moge Allaah tevreden over hem zijn) zei: ''ik reken op mijn slaap zoals ik op mijn nachtwake reken''.', 'One intends by one''s sleep strength for standing in the last part of the night and tomorrow''s fajr; thus one''s sleep becomes worship, as Mu3aadh (may Allaah be pleased with him) said: ''I count on my sleep as I count on my standing''.', 'أثر معاذ شاهد فقه الصحابة في تسيير المباح للآخرة: نومة محتسبة كقومة.', 'De uitspraak van Mu3aadh getuigt van het begrip van de metgezellen: het benutten van het toegestane voor het Hiernamaals — een geïntendeerde slaap gelijk aan een nachtwake.', 'Mu3aadh''s statement testifies to the companions'' understanding: harnessing the permissible for the Hereafter — an intended sleep equal to a night''s standing.', 'آداب النوم وأذكاره', 'tijdstip', 'time', 1, 294),('sleep_cycle', 'time', 'وقفة قصيرة قبل النوم: يستغفر لخطايا يومه، ويعزم على خير غده، ويبيت ولا يحمل لمسلم غلا', 'Een korte zelfverantwoording vóór het slapen: istighfaar voor de fouten van de dag, een voornemen tot het goede van morgen, en slapen zonder wrok jegens een moslim.', 'A brief self-reckoning before sleep: istighfaar for the day''s faults, resolve for tomorrow''s good, and sleeping bearing no rancour toward any Muslim.', 'يجعل سيد الاستغفار وكفارة المجلس خاتمة يومه؛ فيبيت مغفورا له ما كان في مجلس يومه.', 'Men maakt sayyid al-istighfaar en de kaffaarah van de bijeenkomst tot de afsluiting van zijn dag; zo gaat hij de nacht in met vergeving van wat in de bijeenkomst van zijn dag voorviel.', 'One makes sayyid al-istighfaar and the expiation of the gathering the seal of his day; thus he enters the night forgiven of what occurred in the day''s gathering.', 'ومن بات سليم الصدر نال ما شهد به النبي صلى الله عليه وسلم لرجل بالجنة، فكان عمله أنه لا يجد في نفسه غشا لأحد [أحمد (3/166)، وصححه الألباني في المشكاة].', 'Wie de nacht ingaat met een zuiver hart, verkrijgt wat de Profeet (vrede en zegeningen zij met hem) voor een man met het Paradijs getuigde, wiens daad was dat hij geen bedrog jegens iemand koesterde.', 'Whoever enters the night with a sound heart attains what the Prophet (peace and blessings be upon him) testified to Paradise for a man, whose deed was that he harboured no deceit toward anyone.', 'وقفة المحاسبة قبل النوم', 'tijdstip', 'time', 1, 295),('sleep_cycle', 'time', 'ثم يستيقظ لدورة جديدة: مسح النوم، والذكر، والسواك؛ وهكذا عمر المؤمن دورات ذكر متصلة حتى يلقى الله', 'Daarna ontwaakt men voor een nieuwe cyclus: het wegvegen van de slaap, de dhikr en de siwaak — zo is het leven van de gelovige aaneengesloten cycli van dhikr tot hij Allaah ontmoet.', 'Then one wakes to a new cycle: wiping away sleep, the dhikr and the siwaak — thus the believer''s life is continuous cycles of remembrance until he meets Allaah.', 'من نام عن حزبه أو عن شيء منه فقرأه ما بين صلاة الفجر وصلاة الظهر كُتب له كأنما قرأه من الليل [مسلم (747)].', 'Wie zijn (nachtelijk) gedeelte of iets ervan verslaapt en het tussen het fadjr- en het dhuhr-gebed leest, voor hem wordt het geschreven alsof hij het ''s nachts las [Muslim 747].', 'Whoever sleeps through his (night) portion or part of it and reads it between fajr and dhuhr, it is written for him as if he read it at night [Muslim 747].', 'فضل التدارك منصوص في حديث مسلم (747)؛ فلا ييأس من فاته ورد.', 'De verdienste van het inhalen is uitdrukkelijk in Muslims hadieth (747); wie zijn wird mist, wanhope dus niet.', 'The merit of making up is stated in Muslim''s hadeeth (747); so whoever misses his wird should not despair.', 'الاستيقاظ لدورة جديدة', 'tijdstip', 'time', 1, 296),('friday', 'event', 'غسل وتطيب ولبس أحسن الثياب، وتبكير، ومشي، وإنصات للخطبة، وقراءة الكهف، وإكثار من الصلاة على النبي صلى الله عليه وسلم، وتحرّي ساعة الإجابة آخر النهار ــ تقدم تفصيل أذكاره في بابه ــ', 'Vrijdag: de wassing, parfum en de beste kleding; vroeg gaan, te voet; aandachtig luisteren naar de khutbah; soerah al-Kahf; veelvuldig zegeningen over de Profeet (vrede en zegeningen zij met hem); en het zoeken van het uur van verhoring aan het einde van de dag.', 'Friday: the bath, perfume and best clothing; going early on foot; listening attentively to the khutbah; soorah al-Kahf; abundant blessings upon the Prophet (peace and blessings be upon him); and seeking the hour of response at the day''s end.', 'وترك البيع بعد النداء الثاني حرام: ﴿وَذَرُوا الْبَيْعَ﴾ [الجمعة: 9].', 'Het verlaten van de handel na de tweede oproep is verboden: ''en laat de handel'' [al-Djumu3ah 9].', 'Leaving off trade after the second call is forbidden: ''and leave off trade'' [al-Jumu3ah 9].', 'مراتب البُدن والبقر والكبش للمبكرين منصوصة، ومغفرة ما بين الجمعتين لمن أحسنها [مسلم (857)].', 'De rangen van de kamelen, koeien en rammen voor de vroegkomers zijn uitdrukkelijk, en de vergeving van wat tussen de twee vrijdagen ligt voor wie haar goed verricht [Muslim 857].', 'The ranks of camels, cows and rams for the early comers are stated, and forgiveness of what is between the two Fridays for whoever performs it well [Muslim 857].', 'آداب يوم الجمعة', 'wekelijkse periode', 'weekly season', 1, 297),('friday', 'event', 'صيام الاثنين والخميس من كل أسبوع لمن قدر', 'Het vasten van maandag en donderdag voor wie ertoe in staat is; de daden worden dan (aan Allaah) voorgelegd.', 'Fasting Mondays and Thursdays for whoever is able; deeds are then presented (to Allaah).', 'من شق عليه اقتصر على الاثنين أو على ثلاثة أيام من كل شهر.', 'Wie het zwaar valt, beperkt zich tot maandag of tot drie dagen per maand.', 'Whoever finds it hard confines himself to Monday or to three days a month.', 'العلة منصوصة: عرض الأعمال على الله وهو صائم.', 'De reden is uitdrukkelijk: het voorleggen van de daden aan Allaah terwijl hij vast.', 'The reason is stated: the presentation of deeds to Allaah while fasting.', 'صيام الاثنين والخميس', 'wekelijkse periode', 'weekly season', 1, 298),('monthly', 'event', 'ثلاثة أيام من كل شهر، وأفضلها البيض: الثالث عشر والرابع عشر والخامس عشر', 'Drie vastendagen per maand; het beste zijn de witte dagen: de dertiende, veertiende en vijftiende.', 'Three fasting days each month; best are the white days: the 13th, 14th and 15th.', 'من فاتته البيض صام ثلاثا من أي الشهر؛ قالت عائشة: كان يصوم ثلاثة أيام من كل شهر ولا يبالي من أي الشهر صام [مسلم (1160)].', 'Wie de witte dagen mist, vast drie dagen van welk deel van de maand ook; 3aa''ishah zei: hij vastte drie dagen per maand en gaf niet om welk deel van de maand hij vastte.', 'Whoever misses the white days fasts three of any part of the month; 3aa''ishah said: he fasted three days a month, not minding which part of the month he fasted.', 'الأجر منصوص: كصيام الدهر؛ الحسنة بعشر أمثالها.', 'De beloning is uitdrukkelijk: als het vasten van het hele jaar; de goede daad telt tienvoudig.', 'The reward is stated: like fasting the whole year; the good deed counts tenfold.', 'صيام الأيام البيض', 'maandelijkse periode', 'monthly season', 1, 299),('monthly', 'event', 'ذكر رؤية الهلال المتقدم بمتنه وتحريره في بابه', 'De dhikr bij het zien van de nieuwe maan; tekst en toelichting staan in het betreffende hoofdstuk.', 'The dhikr upon sighting the crescent; text and notes are in its chapter.', 'ويترتب على هلالي رمضان وشوال وذي الحجة أحكام الصوم والفطر والنسك؛ فترائيهما فرض كفاية على الأمة.', 'Op de nieuwe manen van Ramadaan, Shawwaal en Dhu-l-hidjdjah berusten de bepalingen van vasten, iftaar en bedevaart; het sighten ervan is een collectieve verplichting (fard kifaayah) voor de gemeenschap.', 'Upon the crescents of Ramadaan, Shawwaal and Dhu-l-hijjah rest the rulings of fasting, breaking fast and pilgrimage; sighting them is a communal obligation (fard kifaayah) upon the community.', 'تقدم.', 'Zoals eerder vermeld.', 'As mentioned earlier.', 'عند رؤية الهلال', 'maandelijkse periode', 'monthly season', 1, 300);